import (
	"cmp"
	"fmt"
	"slices"
)

type Direction int

const (
	ASC Direction = iota
	DESC
)

func SortItems[T cmp.Ordered](items []T, dir Direction) {
	slices.SortFunc(items, func(i, j T) int {
		if dir == ASC {
			return cmp.Compare(i, j)
		} else if dir == DESC {
			return cmp.Compare(j, i)
		} else {
			panic(fmt.Sprintf("Unrecognized sort direction: %d", dir))
		}
	})
}

